"""Replay our existing Matplotlib SVG as editable Artists without rerunning cases.

Only the local, packaged SVG is read. No scripts, links or external resources
inside SVG are executed. Existing embedded raster layers remain raster layers.
The coordinate system is the original SVG page, not reconstructed data axes.
"""
from pathlib import Path as FilePath
import base64
import io
import math
import re
import xml.etree.ElementTree as ET
import numpy as np
from PIL import Image
import matplotlib.pyplot as plt
from matplotlib.path import Path
from matplotlib.patches import PathPatch
from matplotlib.transforms import Affine2D
from fontTools.pens.basePen import BasePen
from fontTools.svgLib.path import parse_path

NUM=r'[-+]?(?:\d*\.\d+|\d+\.?)(?:[eE][-+]?\d+)?'
NS='{http://www.w3.org/2000/svg}'
XLINK='{http://www.w3.org/1999/xlink}href'

def number(s,default=0.0):
    m=re.search(NUM,str(s))
    return float(m.group()) if m else default

def matrix(s):
    out=np.eye(3)
    for op,body in re.findall(r'(matrix|translate|scale|rotate)\s*\(([^)]*)\)',s or ''):
        v=list(map(float,re.findall(NUM,body)));m=np.eye(3)
        if op=='matrix':
            a,b,c,d,e,f=v;m=np.array([[a,c,e],[b,d,f],[0,0,1.]])
        elif op=='translate':m[0,2]=v[0];m[1,2]=v[1] if len(v)>1 else 0
        elif op=='scale':m[0,0]=v[0];m[1,1]=v[1] if len(v)>1 else v[0]
        else:
            t=math.radians(v[0]);m[:2,:2]=[[math.cos(t),-math.sin(t)],[math.sin(t),math.cos(t)]]
            if len(v)==3:
                x,y=v[1:];a=np.eye(3);a[:2,2]=[x,y];b=np.eye(3);b[:2,2]=[-x,-y];m=a@m@b
        out=out@m
    return out

class _Pen(BasePen):
    def __init__(self):super().__init__(None);self.vertices=[];self.codes=[];self.start=None
    def _moveTo(self,p):self.start=p;self.vertices.append(p);self.codes.append(Path.MOVETO)
    def _lineTo(self,p):self.vertices.append(p);self.codes.append(Path.LINETO)
    def _curveToOne(self,a,b,c):self.vertices.extend([a,b,c]);self.codes.extend([Path.CURVE4]*3)
    def _qCurveToOne(self,a,b):self.vertices.extend([a,b]);self.codes.extend([Path.CURVE3]*2)
    def _closePath(self):self.vertices.append(self.start);self.codes.append(Path.CLOSEPOLY)
    def _endPath(self):pass

def path_of(node):
    tag=node.tag.rsplit('}',1)[-1]
    if tag=='path':
        p=_Pen();parse_path(node.get('d',''),p)
        return Path(np.asarray(p.vertices,float).reshape(-1,2),p.codes) if p.codes else None
    if tag=='rect':
        return Path.unit_rectangle().transformed(Affine2D().scale(number(node.get('width')),number(node.get('height'))).translate(number(node.get('x')),number(node.get('y'))))
    return None

def replay(filename):
    root=ET.parse(FilePath(filename)).getroot()
    _,_,width,height=map(float,root.get('viewBox').split())
    fig=plt.figure(figsize=(width/72,height/72),dpi=100)
    ax=fig.add_axes([0,0,1,1]);ax.set_xlim(0,width);ax.set_ylim(height,0);ax.set_axis_off();ax.set_aspect('equal')
    ids={n.get('id'):n for n in root.iter() if n.get('id')}
    counts={'path':0,'text':0,'image':0}
    z=[0]

    def aff(m):return Affine2D(m)+ax.transData

    def clipping(artist,clip,m):
        if not clip:return
        ident=clip.removeprefix('url(#').removesuffix(')');node=ids.get(ident)
        if node is None:return
        for sub in node:
            p=path_of(sub)
            if p is not None:
                artist.set_clip_path(p,aff(m@matrix(node.get('transform'))@matrix(sub.get('transform'))));return

    def walk(node,parent_m,styles,alpha=1.0,parent_id='svg',depth=0,referenced=False,clip_context=None):
        if depth>100:raise ValueError('SVG nesting too deep')
        tag=node.tag.rsplit('}',1)[-1]
        if tag in ('metadata','style','clipPath','defs') and not referenced:return
        m=parent_m@matrix(node.get('transform'))
        st=dict(styles)
        for k,v in re.findall(r'([^:;]+):\s*([^;]+)',node.get('style','')):st[k.strip()]=v.strip()
        for k in ('fill','stroke','stroke-width','opacity','font-size','font-family','font-weight','font-style','text-anchor','clip-path'):
            if node.get(k) is not None:st[k]=node.get(k)
        local_opacity=number(node.get('opacity'),1)
        for k,v in re.findall(r'([^:;]+):\s*([^;]+)',node.get('style','')):
            if k.strip()=='opacity':local_opacity=number(v,1)
        opacity=alpha*local_opacity
        ident=node.get('id') or parent_id
        # SVG clipping belongs to the coordinate system of the node that sets
        # it. A <use> marker's x/y must not also translate its inherited clip.
        own_clip=node.get('clip-path')
        for k,v in re.findall(r'([^:;]+):\s*([^;]+)',node.get('style','')):
            if k.strip()=='clip-path':own_clip=v.strip()
        context=(own_clip,m) if own_clip else clip_context
        clip,clip_m=context if context else (None,m)
        if tag=='use':
            ref=node.get(XLINK,node.get('href',''))
            if ref.startswith('#') and ref[1:] in ids:
                t=np.eye(3);t[:2,2]=[number(node.get('x')),number(node.get('y'))]
                walk(ids[ref[1:]],m@t,st,opacity,ident,depth+1,True,context)
            return
        z[0]+=1
        if tag in ('path','rect'):
            p=path_of(node)
            if p is not None:
                fill=st.get('fill','#000000');stroke=st.get('stroke','none')
                patch=PathPatch(p,facecolor=fill,edgecolor=stroke,linewidth=number(st.get('stroke-width'),1),alpha=opacity,transform=aff(m),zorder=z[0])
                if st.get('stroke-linecap') in ('butt','round','square'):patch.set_capstyle({'square':'projecting'}.get(st['stroke-linecap'],st['stroke-linecap']))
                if st.get('stroke-linejoin') in ('miter','round','bevel'):patch.set_joinstyle(st['stroke-linejoin'])
                if st.get('stroke-dasharray') not in (None,'none'):
                    patch.set_linestyle((number(st.get('stroke-dashoffset')),tuple(map(float,re.findall(NUM,st['stroke-dasharray'])))))
                counts['path']+=1;patch.set_gid(f'{ident}_path_{counts["path"]}');ax.add_patch(patch);clipping(patch,clip,clip_m)
        elif tag in ('text','tspan'):
            # Matplotlib emits mathtext tick labels as independently positioned
            # tspans. Joining them loses both exponent size and placement.
            if tag=='text' and any(c.tag.rsplit('}',1)[-1]=='tspan' for c in node):
                for child in node:walk(child,m,st,opacity,ident,depth+1,clip_context=context)
                return
            content=''.join(node.itertext())
            if content.strip():
                xy=(m@np.array([number(node.get('x')),number(node.get('y')),1]))[:2]
                size=number(st.get('font-size'),8)*math.hypot(m[0,0],m[1,0])
                angle=-math.degrees(math.atan2(m[1,0],m[0,0]))
                ha={'middle':'center','end':'right'}.get(st.get('text-anchor'),'left')
                weight=st.get('font-weight','normal')
                if weight.isdigit():weight=int(weight)
                text=ax.text(*xy,content,fontsize=size,fontfamily='Microsoft YaHei',fontweight=weight,fontstyle=st.get('font-style','normal'),color=st.get('fill','#000000'),ha=ha,va='baseline',rotation=angle,rotation_mode='anchor',alpha=opacity,zorder=z[0])
                counts['text']+=1;text.set_gid(f'{ident}_text_{counts["text"]}');clipping(text,clip,clip_m)
            return
        elif tag=='image':
            href=node.get(XLINK,node.get('href',''))
            if not href.startswith('data:image/'):raise ValueError('External SVG image is not allowed')
            im=np.asarray(Image.open(io.BytesIO(base64.b64decode(href.split(',',1)[1]))))
            x,y,w,h=[number(node.get(k)) for k in ('x','y','width','height')]
            art=ax.imshow(im,extent=(x,x+w,y+h,y),origin='upper',transform=aff(m),interpolation='nearest',zorder=z[0],alpha=opacity,aspect='auto')
            counts['image']+=1;art.set_gid(f'{ident}_image_{counts["image"]}');clipping(art,clip,clip_m)
        for child in node:walk(child,m,st,opacity,ident,depth+1,clip_context=context)

    walk(root,np.eye(3),{'fill':'#000000','stroke':'none'})
    ax.set_xlim(0,width);ax.set_ylim(height,0)
    fig._tavotoo_svg_replay_counts=counts
    return fig
